<span class="line"><span style="color:#D73A49;">    let</span><span style="color:#24292E;"> contractWithSigner </span><span style="color:#D73A49;">=</span><span style="color:#24292E;"> contract.</span><span style="color:#6F42C1;">connect</span><span style="color:#24292E;">(wallet);</span></span>
